[
  {
    "pg_get_functiondef": "CREATE OR REPLACE FUNCTION public.cancel_booking_v1(p_booking_id uuid, p_reason text, p_should_charge boolean DEFAULT false, p_charge_amount numeric DEFAULT NULL::numeric, p_stripe_payment_intent_id text DEFAULT NULL::text, p_stripe_payment_method_id text DEFAULT NULL::text)\n RETURNS jsonb\n LANGUAGE plpgsql\n SECURITY DEFINER\nAS $function$\r\nDECLARE\r\n  v_booking RECORD;\r\n  v_payment_id UUID;\r\n  v_result JSONB;\r\n  v_error_details JSONB;\r\nBEGIN\r\n  -- 1. Obtener y validar la reserva\r\n  SELECT * INTO v_booking\r\n  FROM bookings\r\n  WHERE id = p_booking_id\r\n  FOR UPDATE;\r\n\r\n  IF NOT FOUND THEN\r\n    v_error_details := jsonb_build_object(\r\n      'code', 'BOOKING_NOT_FOUND',\r\n      'message', 'Reserva no encontrada',\r\n      'details', jsonb_build_object('booking_id', p_booking_id)\r\n    );\r\n    RETURN jsonb_build_object('success', false, 'error', v_error_details);\r\n  END IF;\r\n\r\n  IF v_booking.cancelled_at IS NOT NULL THEN\r\n    v_error_details := jsonb_build_object(\r\n      'code', 'BOOKING_ALREADY_CANCELLED',\r\n      'message', 'La reserva ya está cancelada',\r\n      'details', jsonb_build_object(\r\n        'booking_id', p_booking_id,\r\n        'cancelled_at', v_booking.cancelled_at\r\n      )\r\n    );\r\n    RETURN jsonb_build_object('success', false, 'error', v_error_details);\r\n  END IF;\r\n\r\n  -- 2. Si hay cargo, registrar el pago\r\n  IF p_should_charge AND p_charge_amount IS NOT NULL THEN\r\n    INSERT INTO payments (\r\n      booking_id,\r\n      deposit_amount,\r\n      total_price,\r\n      payment_method,\r\n      payment_status,\r\n      stripe_payment_method_id,\r\n      stripe_payment_intent_id,\r\n      notes\r\n    ) VALUES (\r\n      p_booking_id,\r\n      p_charge_amount,\r\n      p_charge_amount,\r\n      'stripe',\r\n      'completed',\r\n      p_stripe_payment_method_id,\r\n      p_stripe_payment_intent_id,\r\n      'Cargo por no-show: ' || COALESCE(p_reason, 'No especificado')\r\n    )\r\n    RETURNING id INTO v_payment_id;\r\n  END IF;\r\n\r\n  -- 3. Actualizar la reserva\r\n  UPDATE bookings\r\n  SET \r\n    cancelled_at = NOW(),\r\n    cancellation_reason = p_reason,\r\n    payment_status = 'cancelled',\r\n    updated_at = NOW()\r\n  WHERE id = p_booking_id;\r\n\r\n  -- 4. Preparar respuesta exitosa\r\n  v_result := jsonb_build_object(\r\n    'success', true,\r\n    'data', jsonb_build_object(\r\n      'booking_id', v_booking.id,\r\n      'cancelled_at', NOW(),\r\n      'reason', p_reason,\r\n      'payment_id', v_payment_id,\r\n      'charge_applied', p_should_charge,\r\n      'charge_amount', p_charge_amount\r\n    )\r\n  );\r\n\r\n  RETURN v_result;\r\n\r\nEXCEPTION WHEN OTHERS THEN\r\n  -- Manejo de errores sin dependencia de tabla error_logs\r\n  v_error_details := jsonb_build_object(\r\n    'code', SQLSTATE,\r\n    'message', SQLERRM,\r\n    'details', jsonb_build_object(\r\n      'booking_id', p_booking_id,\r\n      'error_detail', SQLERRM,\r\n      'error_hint', SQLSTATE\r\n    )\r\n  );\r\n\r\n  RETURN jsonb_build_object('success', false, 'error', v_error_details);\r\nEND;\r\n$function$\n"
  }
]

